messages.content:
Generate a standalone C reproducer that triggers this vulnerability:

File: contrib/pds/tif_pdsdirwrite.c
Line: 590
Function: TIFFWritePerSampleAnys
Bug type: null-pointer-dereference
CWE: CWE-476
Explanation: _TIFFmalloc() is used to allocate an array when samples > 10, but its return value is not checked. If allocation fails, w remains NULL and is dereferenced in w[i] = v, causing a NULL pointer dereference.

Source context:
```c
      550: /*
      551:  * Setup a directory entry that references a
      552:  * samples/pixel array of SHORT values and
      553:  * (potentially) write the associated indirect
      554:  * values.
      555:  */
      556: static int TIFFWritePerSampleShorts(TIFF *tif, ttag_t tag, TIFFDirEntry *dir)
      557: {
      558:     uint16_t buf[10], v;
      559:     uint16_t *w = buf;
      560:     int i, status, samples = tif->tif_dir.td_samplesperpixel;
      561: 
      562:     if (samples > NITEMS(buf))
      563:         w = (uint16_t *)_TIFFmalloc(samples * sizeof(uint16_t));
      564:     TIFFGetField(tif, tag, &v);
      565:     for (i = 0; i < samples; i++)
      566:         w[i] = v;
      567:     status = TIFFWriteShortArray(tif, TIFF_SHORT, tag, dir, samples, w);
      568:     if (w != buf)
      569:         _TIFFfree((char *)w);
      570:     return (status);
      571: }
      572: 
      573: /*
      574:  * Setup a directory entry that references a samples/pixel array of ``type''
      575:  * values and (potentially) write the associated indirect values.  The source
      576:  * data from TIFFGetField() for the specified tag must be returned as double.
      577:  */
      578: static int TIFFWritePerSampleAnys(TIFF *tif, TIFFDataType type, ttag_t tag,
      579:                                   TIFFDirEntry *dir)
      580: {
      581:     double buf[10], v;
      582:     double *w = buf;
      583:     int i, status;
      584:     int samples = (int)tif->tif_dir.td_samplesperpixel;
      585: 
      586:     if (samples > NITEMS(buf))
      587:         w = (double *)_TIFFmalloc(samples * sizeof(double));
      588:     TIFFGetField(tif, tag, &v);
      589:     for (i = 0; i < samples; i++)
>>>   590:         w[i] = v;
      591:     status = TIFFWriteAnyArray(tif, type, tag, dir, samples, w);
      592:     if (w != buf)
      593:         _TIFFfree(w);
      594:     return (status);
      595: }
      596: #undef NITEMS
      597: 
      598: /*
      599:  * Setup a pair of shorts that are returned by
      600:  * value, rather than as a reference to an array.
      601:  */
      602: static int TIFFSetupShortPair(TIFF *tif, ttag_t tag, TIFFDirEntry *dir)
      603: {
      604:     uint16_t v[2];
      605: 
      606:     TIFFGetField(tif, tag, &v[0], &v[1]);
      607:     return (TIFFWriteShortArray(tif, TIFF_SHORT, tag, dir, 2, v));
      608: }
      609: 
      610: /*
      611:  * Setup a directory entry for an NxM table of shorts,
      612:  * where M is known to be 2**bitspersample, and write
      613:  * the associated indirect data.
      614:  */
      615: static int TIFFWriteShortTable(TIFF *tif, ttag_t tag, TIFFDirEntry *dir,
      616:                                uint32_t n, uint16_t **table)
      617: {
      618:     uint32_t i, off;
      619: 
      620:     dir->tdir_tag = tag;
      621:     dir->tdir_type = (short)TIFF_SHORT;
      622:     /* XXX -- yech, fool TIFFWriteData */
      623:     dir->tdir_count = (uint32_t)(1L << tif->tif_dir.td_bitspersample);
      624:     off = tif->tif_dataoff;
      625:     for (i = 0; i < n; i++)
      626:         if (!TIFFWriteData(tif, dir, (char *)table[i]))
      627:             return (0);
      628:     dir->tdir_count *= n;
      629:     dir->tdir_offset = off;
      630:     return (1);
```

The reproducer will be compiled with:
  clang -fsanitize=address -g -O0 -I/tmp/libtiff_upstream reproducer.c -L/tmp/libtiff_upstream/build/.libs -ltiff -lm

The project source root is: /tmp/libtiff_upstream
